/* SBI4U Unit 3 Molecular Genetics: glossary (lessons 3.01–3.07). */
window.GLOSSARY = window.GLOSSARY || [];

window.GLOSSARY.push(
  /* ---------- 3.01 History of Genetics ---------- */
  { term: `Hereditary material`, def: `The molecule that stores the instructions passed from parent to offspring and from cell to daughter cell. Until the 1940s most scientists expected it to be protein (20 amino acids allow far more variety than 4 nucleotides); the experiments of Griffith, Avery, Hershey and Chase showed it is DNA.`, lesson: "3.01", tier: "essential" },
  { term: `Nuclein`, def: `The name Friedrich Miescher (1869) gave to the phosphorus- and nitrogen-rich substance he extracted from the nuclei of white blood cells (from pus on used bandages). It had an acidic portion (what we now call DNA) and a basic portion (protein).`, lesson: "3.01", tier: "essential" },
  { term: `Transformation`, def: `A change in the genetic makeup and traits of a cell caused by taking up genetic material (DNA) from its surroundings. Discovered by Griffith (1928): harmless R-strain bacteria became deadly S-strain bacteria after being mixed with heat-killed S cells, and their offspring stayed S.`, lesson: "3.01", tier: "essential" },
  { term: `Transforming principle`, def: `Griffith's name for the unknown chemical in heat-killed S-strain bacteria that transformed live R-strain bacteria. Avery, MacLeod and McCarty (1944) showed that it is DNA.`, lesson: "3.01", tier: "essential" },
  { term: `S strain (smooth)`, def: `The virulent (disease-causing) strain of <em>Streptococcus pneumoniae</em> used by Griffith. Its polysaccharide capsule gives smooth colonies and hides the cell from the mouse's immune system, so injected mice died of pneumonia.`, lesson: "3.01", tier: "essential" },
  { term: `R strain (rough)`, def: `The non-virulent strain of <em>Streptococcus pneumoniae</em> used by Griffith. It lacks the capsule (rough colonies), so the immune system destroys it and injected mice live.`, lesson: "3.01", tier: "essential" },
  { term: `Virulent`, def: `Able to cause disease. In Griffith's experiment the S strain was virulent and the R strain was non-virulent (avirulent).`, lesson: "3.01", tier: "likely" },
  { term: `Heat-killed`, def: `Killed by heating, which destroys the cell and denatures most of its proteins. DNA survives heating better than protein, which is why heat-killed S cells could still transform R cells in Griffith's experiment.`, lesson: "3.01", tier: "likely" },
  { term: `Acetabularia`, def: `<em>Acetabularia</em> is a giant single-celled green alga (2–5 cm tall) with a cap, a stalk and a foot (rhizoid). Hämmerling (1934) used it because one cell is big enough to cut and graft, and its single nucleus sits in the foot.`, lesson: "3.01", tier: "essential" },
  { term: `Rhizoid (foot)`, def: `The root-like base of <em>Acetabularia</em> that anchors it and contains the nucleus. When Hämmerling cut off the cap, a new cap regrew from the part with the foot; a removed foot did not regrow, showing the hereditary information is in the foot, where the nucleus is.`, lesson: "3.01", tier: "essential" },
  { term: `Grafting (Hämmerling)`, def: `Joining the stalk of one <em>Acetabularia</em> species to the foot of another (<em>A. crenulata</em> and <em>A. mediterranea</em>). The cap that eventually grew matched the species that supplied the foot, and therefore the nucleus.`, lesson: "3.01", tier: "likely" },
  { term: `Protease`, def: `An enzyme that breaks down proteins by hydrolyzing peptide bonds. In the Avery, MacLeod and McCarty experiment, protease-treated S-strain extract still transformed R cells, so protein is not the transforming principle.`, lesson: "3.01", tier: "essential" },
  { term: `RNase (ribonuclease)`, def: `An enzyme that breaks down RNA. RNase-treated S-strain extract still caused transformation, ruling out RNA as the transforming principle.`, lesson: "3.01", tier: "essential" },
  { term: `DNase (deoxyribonuclease)`, def: `An enzyme that breaks down DNA. It was the only enzyme that stopped transformation in the Avery, MacLeod and McCarty experiment, which showed that DNA is the transforming principle.`, lesson: "3.01", tier: "essential" },
  { term: `Chargaff's rules`, def: `In double-stranded DNA, the amount of adenine equals thymine (A = T) and guanine equals cytosine (G = C), so purines = pyrimidines. The ratio (A + T) to (G + C) varies from species to species. Found by Erwin Chargaff (1950) using chromatography.`, lesson: "3.01", tier: "essential" },
  { term: `Chromatography`, def: `A technique that separates the parts of a mixture by how fast they move through a medium such as paper. Chargaff used it to separate and measure the four bases in DNA from different species.`, lesson: "3.01", tier: "likely" },
  { term: `Bacteriophage (phage)`, def: `A virus that infects bacteria. A phage is just a protein coat around a DNA core; it injects its genetic material into the host, which then builds new phages. Hershey and Chase used the T2 phage of <em>E. coli</em>.`, lesson: "3.01", tier: "essential" },
  { term: `Radioactive isotope (radioisotope)`, def: `An unstable form of an element that gives off radiation, so it can be traced. Hershey and Chase labelled phage protein with <sup>35</sup>S (proteins contain sulfur, DNA does not) and phage DNA with <sup>32</sup>P (DNA is rich in phosphorus).`, lesson: "3.01", tier: "essential" },
  { term: `Supernatant`, def: `The liquid left above the pellet after centrifugation. In the Hershey–Chase experiment it held the empty phage coats, so it contained the <sup>35</sup>S label.`, lesson: "3.01", tier: "essential" },
  { term: `Pellet`, def: `The solid that collects at the bottom of a tube after centrifugation. In the Hershey–Chase experiment it held the heavier bacterial cells and the phage DNA inside them, so it contained the <sup>32</sup>P label.`, lesson: "3.01", tier: "essential" },
  { term: `X-ray diffraction`, def: `A method in which X-rays are passed through a crystal or fibre and scatter into a pattern of spots that reveals the shape and repeating distances of the molecule. Franklin used it to show DNA is a helix with its sugar-phosphate backbone on the outside.`, lesson: "3.01", tier: "essential" },
  { term: `Photo 51`, def: `Rosalind Franklin's 1952 X-ray diffraction photo of the B form of DNA (taken with her student Raymond Gosling). Its X-shaped pattern showed a helix, and its spacings gave the 3.4 nm repeat and 2 nm width used in the Watson–Crick model.`, lesson: "3.01", tier: "likely" },
  { term: `A form and B form of DNA`, def: `Two shapes of DNA found by Franklin. The A form is the drier, more compact form; the B form is the wetter form found in cells (2 nm wide, 10 bp per turn). The class case files call them the dry and wet forms.`, lesson: "3.01", tier: "likely" },
  { term: `Conservative replication`, def: `A hypothesis (rejected) that the parent double helix stays intact and a completely new double helix is made. Meselson and Stahl ruled it out because generation 1 gave a single hybrid band, not a heavy band plus a light band.`, lesson: "3.01", tier: "essential" },
  { term: `Dispersive replication`, def: `A hypothesis (rejected) that each new double helix is a patchwork of old and new pieces on both strands. Meselson and Stahl ruled it out because generation 2 gave two bands (hybrid and light), not one band of intermediate density.`, lesson: "3.01", tier: "essential" },
  { term: `Semiconservative replication`, def: `The way DNA really copies itself: each strand of the parent serves as a template for a new strand, so each daughter double helix has one parent (old) strand and one new strand. Shown by Meselson and Stahl (1958).`, lesson: "3.01", tier: "essential" },
  { term: `Heavy nitrogen (<sup>15</sup>N)`, def: `A stable, non-radioactive isotope of nitrogen with one more neutron than ordinary <sup>14</sup>N. Bacteria grown on <sup>15</sup>N build it into their DNA bases, making the DNA denser; Meselson and Stahl used this to tell old and new strands apart.`, lesson: "3.01", tier: "essential" },
  { term: `Density-gradient centrifugation`, def: `Spinning DNA at very high speed in a caesium chloride (CsCl) solution, which forms a gradient of density in the tube. Each DNA molecule settles as a band where its density matches the solution, so heavy (<sup>15</sup>N), hybrid and light (<sup>14</sup>N) DNA form separate bands.`, lesson: "3.01", tier: "essential" },
  { term: `Hybrid DNA (Meselson–Stahl)`, def: `A double helix with one heavy (<sup>15</sup>N) strand and one light (<sup>14</sup>N) strand. It forms a band halfway between heavy and light DNA. After any number of generations exactly two hybrid molecules remain per original molecule (2 of 16 = 12.5% after 4 generations).`, lesson: "3.01", tier: "likely" },

  /* ---------- 3.02 DNA Structure ---------- */
  { term: `Nucleic acid`, def: `A polymer of nucleotides that stores and transmits hereditary information that determines an organism's structural and functional characteristics. The two kinds are DNA and RNA.`, lesson: "3.02", tier: "essential" },
  { term: `DNA (deoxyribonucleic acid)`, def: `The double-stranded nucleic acid that contains the instructions for building an organism. Its nucleotides contain deoxyribose and the bases A, T, G and C; two antiparallel strands wind into a double helix.`, lesson: "3.02", tier: "essential" },
  { term: `RNA (ribonucleic acid)`, def: `The usually single-stranded nucleic acid that is used to make proteins: mRNA copies a gene, rRNA forms the ribosome, and tRNA carries amino acids. Its nucleotides contain ribose and the bases A, U, G and C.`, lesson: "3.02", tier: "essential" },
  { term: `Nucleotide`, def: `The monomer of a nucleic acid, made of a 5-carbon sugar (deoxyribose in DNA, ribose in RNA), a phosphate group on the 5′ carbon and a nitrogenous base on the 1′ carbon.`, lesson: "3.02", tier: "essential" },
  { term: `Deoxyribose`, def: `The 5-carbon sugar in DNA. It has an H instead of an OH on its 2′ carbon ("one less oxygen"), which makes DNA more chemically stable than RNA.`, lesson: "3.02", tier: "essential" },
  { term: `Ribose`, def: `The 5-carbon sugar in RNA. It has an –OH group on its 2′ carbon, which makes RNA more reactive and shorter-lived than DNA.`, lesson: "3.02", tier: "essential" },
  { term: `Prime numbering (1′–5′)`, def: `The numbering of the carbons in the sugar of a nucleotide, read with "prime" (′) to tell them apart from the atoms in the base. The base attaches at 1′, the 2′ carbon has H (DNA) or OH (RNA), the 3′ carbon carries the –OH that bonds to the next nucleotide, and the phosphate is on 5′.`, lesson: "3.02", tier: "essential" },
  { term: `Nitrogenous base`, def: `The nitrogen-containing ring part of a nucleotide: adenine, guanine, cytosine, thymine (DNA only) or uracil (RNA only). The sequence of the four bases in DNA determines the structure of proteins.`, lesson: "3.02", tier: "essential" },
  { term: `Purine`, def: `A nitrogenous base with a double-ring structure: adenine (A) and guanine (G). In DNA a purine always pairs with a pyrimidine.`, lesson: "3.02", tier: "essential" },
  { term: `Pyrimidine`, def: `A nitrogenous base with a single-ring structure: cytosine (C), thymine (T, DNA only) and uracil (U, RNA only).`, lesson: "3.02", tier: "essential" },
  { term: `Adenine (A)`, def: `A purine base. In DNA it pairs with thymine by two hydrogen bonds; in RNA it pairs with uracil.`, lesson: "3.02", tier: "essential" },
  { term: `Guanine (G)`, def: `A purine base that pairs with cytosine by three hydrogen bonds.`, lesson: "3.02", tier: "essential" },
  { term: `Cytosine (C)`, def: `A pyrimidine base found in both DNA and RNA. It pairs with guanine by three hydrogen bonds.`, lesson: "3.02", tier: "essential" },
  { term: `Thymine (T)`, def: `A pyrimidine base found only in DNA. It pairs with adenine by two hydrogen bonds; in RNA it is replaced by uracil.`, lesson: "3.02", tier: "essential" },
  { term: `Uracil (U)`, def: `A pyrimidine base found only in RNA, in place of thymine. It pairs with adenine.`, lesson: "3.02", tier: "essential" },
  { term: `Phosphodiester bond`, def: `The strong covalent bond that links nucleotides in a strand: the phosphate on the 5′ carbon of one nucleotide bonds to the 3′ –OH of the sugar of the previous one. Repeated phosphodiester bonds form the sugar-phosphate backbone.`, lesson: "3.02", tier: "essential" },
  { term: `Sugar-phosphate backbone`, def: `The alternating chain of sugars and phosphates joined by phosphodiester bonds that forms the outside of each DNA strand. The bases point inward from it, and its phosphate groups make DNA slightly acidic and negatively charged.`, lesson: "3.02", tier: "essential" },
  { term: `5′ end`, def: `The end of a nucleic acid strand that terminates in a phosphate group (on the 5′ carbon of the last sugar).`, lesson: "3.02", tier: "essential" },
  { term: `3′ end`, def: `The end of a nucleic acid strand that terminates in the sugar, with a free –OH on its 3′ carbon. New nucleotides can only be added here.`, lesson: "3.02", tier: "essential" },
  { term: `Antiparallel`, def: `Running in opposite directions. The two strands of DNA are antiparallel: one runs 5′ → 3′ and its partner runs 3′ → 5′ alongside it.`, lesson: "3.02", tier: "essential" },
  { term: `Complementary base pairing`, def: `The rule that A pairs only with T (U in RNA) by two hydrogen bonds and G pairs only with C by three. A purine always pairs with a pyrimidine, which keeps the helix 2 nm wide, and each strand predicts the sequence of its partner.`, lesson: "3.02", tier: "essential" },
  { term: `Hydrogen bond (in DNA)`, def: `A weak attraction between a slightly positive H atom on one base and a slightly negative O or N atom on its partner. Two join A–T and three join G–C; one is weak, but millions together hold the strands firmly while still letting them be unzipped.`, lesson: "3.02", tier: "essential" },
  { term: `Double helix`, def: `The shape of DNA: two antiparallel strands wound around each other like a twisted ladder, with the sugar-phosphate backbones on the outside and paired bases inside. It is 2 nm wide, with 10 base pairs and 3.4 nm per turn and 0.34 nm between base pairs.`, lesson: "3.02", tier: "essential" },
  { term: `Major and minor grooves`, def: `The two unequal grooves that spiral along the outside of the double helix, because the two backbones are not evenly spaced. Proteins such as transcription factors and repressors read the base sequence mostly through the major groove.`, lesson: "3.02", tier: "likely" },
  { term: `Base stacking`, def: `The attraction between the flat, stacked base pairs inside the helix. Along with the many hydrogen bonds, it gives DNA its structural stability.`, lesson: "3.02", tier: "likely" },
  { term: `GC content`, def: `The percentage of base pairs in DNA that are G–C. DNA with more G–C pairs has more hydrogen bonds (3 per pair instead of 2) and stronger stacking, so it needs a higher temperature to separate its strands.`, lesson: "3.02", tier: "likely" },
  { term: `Histone`, def: `A small, positively charged protein that DNA (negatively charged) wraps around in eukaryotic cells. Eight histones form the core of each nucleosome.`, lesson: "3.02", tier: "likely" },
  { term: `Nucleosome`, def: `The basic unit of DNA packing in eukaryotes: about 146 bp of DNA wrapped almost twice around a core of eight histone proteins, like thread on a spool ("beads on a string").`, lesson: "3.02", tier: "likely" },
  { term: `Chromatin`, def: `The complex of DNA and proteins (mainly histones) that makes up eukaryotic chromosomes. Loosely packed euchromatin can be transcribed; tightly packed heterochromatin is mostly silent.`, lesson: "3.02", tier: "likely" },
  { term: `Chromosome`, def: `One long DNA molecule with its packing proteins. Eukaryotic chromosomes are linear and capped by telomeres; a bacterial chromosome is usually a single circle.`, lesson: "3.02", tier: "likely" },
  { term: `Telomere`, def: `The repeating 6-base-pair sequence 5′-TTAGGG-3′ (in humans, repeated thousands of times) at the ends of linear chromosomes. It contains no genes; it protects the ends and is shortened a little at each cell division.`, lesson: "3.02", tier: "essential" },
  { term: `Telomere cap (shelterin)`, def: `The group of proteins that bind the telomere to form a protective cap (shelterin: TRF1, TRF2, POT1, TIN2, TPP1, RAP1). The 3′ overhang tucks back into the double strand to form a T-loop, so the cell does not mistake the chromosome end for broken DNA.`, lesson: "3.02", tier: "likely" },
  { term: `T-loop`, def: `The loop formed when the single-stranded 3′ overhang of a telomere folds back and tucks into the double-stranded TTAGGG repeats, hiding the chromosome end.`, lesson: "3.02", tier: "likely" },
  { term: `Telomerase`, def: `An enzyme that lengthens telomeres. It carries its own RNA template and acts as a reverse transcriptase, adding TTAGGG repeats to the 3′ end. Active in germ cells, stem cells and most cancer cells, but switched off in most body cells.`, lesson: "3.02", tier: "likely" },
  { term: `Hayflick limit`, def: `The limited number of times (about 40–60) a normal human body cell can divide in culture before its telomeres become too short and it stops dividing.`, lesson: "3.02", tier: "likely" },
  { term: `Senescence`, def: `A permanent state in which a cell is alive but no longer divides. Cells enter it when their telomeres run out; the alternative is apoptosis.`, lesson: "3.02", tier: "likely" },
  { term: `Apoptosis`, def: `Programmed cell death: an orderly self-destruction a cell carries out when it is damaged beyond repair, for example when its telomeres are critically short.`, lesson: "3.02", tier: "likely" },

  /* ---------- 3.03 DNA Replication ---------- */
  { term: `DNA replication`, def: `The copying of DNA before a cell divides, so each daughter cell gets a complete, identical set of genetic instructions. It is semiconservative and happens in the S phase of interphase, before mitosis.`, lesson: "3.03", tier: "essential" },
  { term: `S phase`, def: `The synthesis phase of interphase, when DNA is replicated. It comes after G<sub>1</sub> and before G<sub>2</sub> and mitosis.`, lesson: "3.03", tier: "essential" },
  { term: `Template`, def: `A strand of nucleic acid whose base sequence is used to build a complementary strand. In replication both parent strands are templates; in transcription only the template strand of a gene is.`, lesson: "3.03", tier: "essential" },
  { term: `Parental strand and daughter strand`, def: `In replication, the parental (parent) strand is an original strand used as a template; the daughter strand is the new complementary strand built on it.`, lesson: "3.03", tier: "essential" },
  { term: `Origin of replication`, def: `A specific sequence where replication begins and the helix is first opened. A circular bacterial chromosome has one origin; each linear eukaryotic chromosome has thousands.`, lesson: "3.03", tier: "essential" },
  { term: `Replication bubble`, def: `The opened region of DNA at an origin, with a replication fork at each end. In eukaryotes many bubbles form along each chromosome and grow until they merge.`, lesson: "3.03", tier: "essential" },
  { term: `Replication fork`, def: `The Y-shaped region where helicase is unwinding the parent DNA and the two new strands are being made.`, lesson: "3.03", tier: "essential" },
  { term: `Bidirectional replication`, def: `Replication moving in both directions away from an origin, because each bubble has two forks that travel in opposite directions.`, lesson: "3.03", tier: "essential" },
  { term: `DNA helicase`, def: `The enzyme that unwinds and "unzips" the double helix at the replication fork by breaking the hydrogen bonds between complementary bases, exposing the two template strands.`, lesson: "3.03", tier: "essential" },
  { term: `Single-stranded binding proteins (SSBs)`, def: `Proteins that coat the exposed single strands at the fork so they cannot re-form hydrogen bonds with each other (or fold back on themselves) before they are copied.`, lesson: "3.03", tier: "essential" },
  { term: `Topoisomerase`, def: `The enzyme that relieves the twisting tension (supercoiling) building up ahead of the fork as the helix unwinds. It cuts the DNA backbone, lets it untwist and reseals it; it works ahead of the fork at the same time as helicase.`, lesson: "3.03", tier: "essential" },
  { term: `DNA gyrase`, def: `The topoisomerase of bacteria (a type II topoisomerase). The class answer key uses this name in one sentence; "topoisomerase" is the general name to use.`, lesson: "3.03", tier: "likely" },
  { term: `Supercoiling`, def: `Extra twisting of the double helix on itself. Unwinding DNA at the fork overwinds the DNA ahead of it, like pulling apart the strands of a rope; topoisomerase removes this tension.`, lesson: "3.03", tier: "likely" },
  { term: `Primase (RNA primase)`, def: `The enzyme that makes a short RNA primer (about 10 nucleotides) complementary to the template, giving DNA polymerase a free 3′-OH to build on. Needed once for the leading strand and for every Okazaki fragment.`, lesson: "3.03", tier: "essential" },
  { term: `RNA primer`, def: `A short strand of RNA nucleotides laid down by primase at the start of each new DNA strand or fragment. DNA polymerase III extends it; DNA polymerase I later removes it and replaces it with DNA.`, lesson: "3.03", tier: "essential" },
  { term: `Free 3′-OH`, def: `The exposed hydroxyl group on the 3′ carbon at the end of a growing strand. DNA polymerases can only add a nucleotide to it, which is why they need a primer and why new strands grow 5′ → 3′.`, lesson: "3.03", tier: "essential" },
  { term: `DNA polymerase III`, def: `The main replication enzyme in bacteria. Starting from an RNA primer, it adds complementary DNA nucleotides to the free 3′ end of the growing new strand, reading the template 3′ → 5′ and building 5′ → 3′. It also proofreads.`, lesson: "3.03", tier: "essential" },
  { term: `DNA polymerase I`, def: `The bacterial enzyme that removes RNA primers and replaces them with DNA nucleotides. It also proofreads and acts as an exonuclease.`, lesson: "3.03", tier: "essential" },
  { term: `DNA ligase`, def: `The enzyme that seals the nicks left in the backbone after primers are replaced, joining Okazaki fragments by forming phosphodiester bonds ("molecular glue").`, lesson: "3.03", tier: "essential" },
  { term: `Deoxyribonucleoside triphosphate (dNTP)`, def: `A free DNA building block carrying three phosphates (dATP, dTTP, dGTP, dCTP). When polymerase adds it to a strand, two phosphates are released (as pyrophosphate), and that energy drives formation of the phosphodiester bond.`, lesson: "3.03", tier: "likely" },
  { term: `Leading strand`, def: `The new strand built continuously toward the replication fork, following helicase. It needs only one RNA primer.`, lesson: "3.03", tier: "essential" },
  { term: `Lagging strand`, def: `The new strand built discontinuously, away from the replication fork, in short Okazaki fragments. It needs many RNA primers, one per fragment.`, lesson: "3.03", tier: "essential" },
  { term: `Okazaki fragment`, def: `A short piece of new DNA on the lagging strand (about 1,000–2,000 nucleotides in bacteria, 100–200 in eukaryotes), each started by its own RNA primer and later joined to the next by DNA ligase.`, lesson: "3.03", tier: "essential" },
  { term: `Nick`, def: `A break in one sugar-phosphate backbone of double-stranded DNA where a phosphodiester bond is missing, for example between two Okazaki fragments. DNA ligase seals it.`, lesson: "3.03", tier: "likely" },
  { term: `Proofreading`, def: `Checking each newly added nucleotide against the template. DNA polymerases I and III back up, remove a mismatched nucleotide (as exonucleases) and insert the correct one, cutting errors from about 1 in 10,000 to about 1 in 10 million.`, lesson: "3.03", tier: "essential" },
  { term: `Exonuclease`, def: `An enzyme activity that removes nucleotides one at a time from the end of a strand. DNA polymerases I and III use it to remove wrong nucleotides; DNA pol I also uses it to remove primers.`, lesson: "3.03", tier: "essential" },
  { term: `Mismatch repair`, def: `Repair after replication in which proteins find a wrongly paired base missed by proofreading, cut out a stretch of the new strand containing it, and resynthesize it correctly. Together with proofreading, it brings the final error rate to about 1 in a billion.`, lesson: "3.03", tier: "likely" },
  { term: `Excision repair (nucleotide excision repair)`, def: `Repair of damaged DNA, such as a thymine dimer, in which a nuclease cuts out the damaged section of one strand, DNA polymerase fills the gap using the other strand as a template, and ligase seals it.`, lesson: "3.03", tier: "likely" },
  { term: `Thymine dimer`, def: `Two adjacent thymines on the same strand that UV light has bonded together covalently, kinking the helix and blocking replication. Fixed by excision repair, mainly in skin cells.`, lesson: "3.03", tier: "likely" },
  { term: `Nuclease`, def: `Any enzyme that cuts nucleic acids by breaking phosphodiester bonds. Endonucleases cut inside a strand; exonucleases remove nucleotides from an end.`, lesson: "3.03", tier: "likely" },
  { term: `End-replication problem`, def: `On a linear chromosome, the RNA primer at the very end of the lagging strand cannot be replaced with DNA (there is no upstream 3′-OH to build from), so each round of replication leaves the chromosome slightly shorter. Telomeres absorb the loss.`, lesson: "3.03", tier: "likely" },

  /* ---------- 3.04 Transcription ---------- */
  { term: `Central dogma`, def: `The one-way flow of genetic information in cells: DNA → RNA (transcription) → protein (translation). DNA also copies itself (replication). Retroviruses are an exception: reverse transcriptase copies RNA into DNA.`, lesson: "3.04", tier: "essential" },
  { term: `Protein synthesis`, def: `Making a polypeptide from the instructions in a gene, in two stages: transcription (DNA → mRNA, in the nucleus) and translation (mRNA → polypeptide, at a ribosome in the cytosol).`, lesson: "3.04", tier: "essential" },
  { term: `Gene`, def: `A segment of DNA that codes for a protein (or a functional RNA). It contains a promoter located upstream and a terminator located downstream of the transcribed region.`, lesson: "3.04", tier: "essential" },
  { term: `Gene expression`, def: `Using the information in a gene to make its product (an RNA and usually a protein), through transcription and translation. Cells control which genes are expressed and how much.`, lesson: "3.04", tier: "likely" },
  { term: `Transcription`, def: `Copying the sequence of a gene from DNA into RNA. RNA polymerase reads the template strand 3′ → 5′ and builds RNA 5′ → 3′ in three phases: initiation, elongation and termination. It happens in the nucleus (eukaryotes) or nucleoid (prokaryotes).`, lesson: "3.04", tier: "essential" },
  { term: `Promoter`, def: `The DNA sequence upstream of a gene (or operon) where RNA polymerase and transcription factors bind to start transcription. In many eukaryotic genes it contains a TATA box.`, lesson: "3.04", tier: "essential" },
  { term: `TATA box`, def: `A short promoter sequence rich in T and A (5′-TATAAA-3′ on the coding strand), about 25–30 bp upstream of the transcription start site. TATA-binding protein binds it first; A–T pairs (two H-bonds) make this region easy to open.`, lesson: "3.04", tier: "essential" },
  { term: `Transcription factor`, def: `A protein that binds to specific sequences of DNA in the promoter region and serves as a pointer for RNA polymerase, showing it which gene to transcribe. Active during initiation.`, lesson: "3.04", tier: "essential" },
  { term: `TATA-binding protein (TBP)`, def: `The transcription factor that binds the TATA box first, bending the DNA and marking the spot where other transcription factors and RNA polymerase assemble.`, lesson: "3.04", tier: "essential" },
  { term: `RNA polymerase`, def: `The enzyme that transcribes DNA into RNA. It binds the promoter, unwinds about 10–20 bp of DNA, reads the template strand 3′ → 5′ and joins ribonucleotides 5′ → 3′. It needs no primer and has no proofreading.`, lesson: "3.04", tier: "essential" },
  { term: `RNA polymerase II`, def: `The eukaryotic RNA polymerase that transcribes protein-coding genes into pre-mRNA (RNA pol I makes most rRNA, RNA pol III makes tRNA).`, lesson: "3.04", tier: "likely" },
  { term: `Template strand (antisense, non-coding)`, def: `The DNA strand of a gene that RNA polymerase reads, 3′ → 5′. The mRNA is complementary to it.`, lesson: "3.04", tier: "essential" },
  { term: `Coding strand (sense, non-template)`, def: `The DNA strand of a gene that is not used in transcription. It runs 5′ → 3′ and has the same sequence as the mRNA, except with T in place of U.`, lesson: "3.04", tier: "essential" },
  { term: `Upstream and downstream`, def: `Directions along a gene relative to transcription: upstream is toward the 5′ end of the coding strand (where the promoter is); downstream is toward the 3′ end (where the terminator is).`, lesson: "3.04", tier: "essential" },
  { term: `Transcription start site`, def: `The first DNA base pair that is copied into RNA, just downstream of the promoter.`, lesson: "3.04", tier: "likely" },
  { term: `Terminator`, def: `The DNA sequence downstream of a gene that signals the end of transcription. When RNA polymerase transcribes it, the primary transcript is released from the template.`, lesson: "3.04", tier: "essential" },
  { term: `Initiation`, def: `The first phase of a process. Transcription: RNA polymerase binds the promoter (TATA box) with transcription factors and opens the helix. Translation: the small subunit binds the 5′ cap, scans to AUG, the Met-tRNA pairs with it and the large subunit joins.`, lesson: "3.04", tier: "essential" },
  { term: `Elongation`, def: `The middle phase of a process. Transcription: RNA polymerase moves along the template adding ribonucleotides 5′ → 3′. Translation: the ribosome adds one amino acid per codon as it moves 5′ → 3′ along the mRNA.`, lesson: "3.04", tier: "essential" },
  { term: `Termination`, def: `The last phase of a process. Transcription: RNA polymerase transcribes the terminator and releases the transcript. Translation: a stop codon enters the A site, a release factor binds and the polypeptide is released.`, lesson: "3.04", tier: "essential" },
  { term: `Primary transcript`, def: `The RNA made directly by transcription, before any processing. In eukaryotes it is called pre-mRNA.`, lesson: "3.04", tier: "essential" },
  { term: `Pre-mRNA`, def: `The primary transcript of a eukaryotic gene. It still contains introns and must get a 5′ cap, a poly-A tail and be spliced before it leaves the nucleus as mature mRNA.`, lesson: "3.04", tier: "essential" },
  { term: `mRNA (messenger RNA)`, def: `RNA that is complementary to a specific gene in DNA and carries its code (as codons) out of the nucleus into the cytosol, where ribosomes translate it.`, lesson: "3.04", tier: "essential" },
  { term: `rRNA (ribosomal RNA)`, def: `RNA that binds with proteins to form the ribosomes. It makes up most of a ribosome's mass and catalyzes peptide bond formation.`, lesson: "3.04", tier: "essential" },
  { term: `tRNA (transfer RNA)`, def: `Small RNA that carries a specific amino acid to the growing polypeptide chain, matching its anticodon to the codons on the mRNA.`, lesson: "3.04", tier: "essential" },
  { term: `snRNA (small nuclear RNA)`, def: `Short RNAs in the nucleus that combine with proteins to form spliceosomes, which cut introns out of pre-mRNA. Listed in the class answer key as a fourth type of RNA made by transcription.`, lesson: "3.04", tier: "essential" },
  { term: `Ribonucleotide`, def: `An RNA building block: ribose, a phosphate and one of the bases A, U, G or C. RNA polymerase joins ribonucleoside triphosphates (ATP, UTP, GTP, CTP) into RNA.`, lesson: "3.04", tier: "likely" },
  { term: `5′ cap`, def: `A modified guanine nucleotide (7-methylguanosine) added to the 5′ end of pre-mRNA. It prevents degradation and is recognized by the small ribosomal subunit to start translation.`, lesson: "3.04", tier: "essential" },
  { term: `Poly-A tail`, def: `A chain of about 200 adenine ribonucleotides added to the 3′ end of pre-mRNA after it is cut just past the AAUAAA signal. It prevents degradation and helps export and translation.`, lesson: "3.04", tier: "essential" },
  { term: `Polyadenylation signal (AAUAAA)`, def: `The sequence near the 3′ end of a pre-mRNA that tells enzymes to cut the transcript about 10–30 nucleotides further on and add the poly-A tail. In eukaryotes this ends transcription.`, lesson: "3.04", tier: "likely" },
  { term: `Intron`, def: `A non-coding region of a gene and its pre-mRNA that is removed by splicing ("intron = in between, taken out").`, lesson: "3.04", tier: "essential" },
  { term: `Exon`, def: `A coding region of a gene that remains in the mature mRNA after splicing and is joined to the other exons ("exon = expressed").`, lesson: "3.04", tier: "essential" },
  { term: `Splicing`, def: `Removal of introns from pre-mRNA and joining of the exons, done in the nucleus by spliceosomes.`, lesson: "3.04", tier: "essential" },
  { term: `Spliceosome`, def: `A large complex of snRNAs and proteins that recognizes the ends of each intron, cuts it out as a loop (lariat) and joins the neighbouring exons.`, lesson: "3.04", tier: "essential" },
  { term: `Alternative splicing`, def: `Joining a gene's exons in different combinations (for example, skipping an exon) so one gene can make several different proteins. It helps explain how about 20,000 human genes make many more kinds of protein.`, lesson: "3.04", tier: "likely" },
  { term: `Mature mRNA`, def: `The processed mRNA (5′ cap, exons only, poly-A tail) that leaves the nucleus through a nuclear pore to be translated by ribosomes.`, lesson: "3.04", tier: "essential" },
  { term: `Untranslated region (UTR)`, def: `The parts of an mRNA that are not translated: the 5′ UTR between the cap and the start codon, and the 3′ UTR between the stop codon and the poly-A tail.`, lesson: "3.04", tier: "likely" },
  { term: `Nucleoid`, def: `The region of a prokaryotic cell where its DNA is found. It is not enclosed by a membrane, so transcription happens there and translation can begin while transcription is still going.`, lesson: "3.04", tier: "essential" },
  { term: `Reverse transcriptase`, def: `An enzyme that builds DNA from an RNA template, the reverse of transcription. Retroviruses such as HIV use it to copy their RNA genome into DNA; telomerase is a specialized reverse transcriptase.`, lesson: "3.04", tier: "extra" },

  /* ---------- 3.05 Translation ---------- */
  { term: `Translation`, def: `Decoding the base sequence of mRNA into the amino acid sequence of a polypeptide, at a ribosome in the cytosol (free or on the rough ER). The ribosome moves 5′ → 3′ along the mRNA, adding one amino acid per codon.`, lesson: "3.05", tier: "essential" },
  { term: `Genetic code`, def: `The set of rules by which mRNA codons are read as amino acids: 64 codons (4<sup>3</sup>) for 20 amino acids plus start and stop signals. It is redundant, unambiguous, non-overlapping and nearly universal.`, lesson: "3.05", tier: "essential" },
  { term: `Codon`, def: `A sequence of 3 mRNA nucleotides that codes for one amino acid or a stop signal.`, lesson: "3.05", tier: "essential" },
  { term: `Triplet code`, def: `The fact that the code is read in groups of three bases. Two-base codons would give only 4<sup>2</sup> = 16 combinations, too few for 20 amino acids; three bases give 4<sup>3</sup> = 64.`, lesson: "3.05", tier: "likely" },
  { term: `Start codon`, def: `AUG, which codes for methionine and signals that translation commences at that point. The first AUG from the 5′ end sets the reading frame.`, lesson: "3.05", tier: "essential" },
  { term: `Stop codon`, def: `UAA, UAG or UGA. A stop codon codes for no amino acid and no tRNA matches it; a release factor protein recognizes it in the A site and translation ends.`, lesson: "3.05", tier: "essential" },
  { term: `Redundancy (degeneracy) of the code`, def: `More than one codon codes for most amino acids (61 sense codons for 20 amino acids). It minimizes errors: many changes in the third base still give the same amino acid.`, lesson: "3.05", tier: "essential" },
  { term: `Universality of the code`, def: `Almost every organism uses the same codon meanings, evidence of common ancestry; it lets bacteria make human proteins such as insulin. A few small exceptions exist (for example in mitochondria).`, lesson: "3.05", tier: "likely" },
  { term: `Reading frame`, def: `The way an mRNA is divided into consecutive, non-overlapping codons, set by the start codon. Any sequence can be read in three frames; keeping the correct one ensures the right amino acids are used.`, lesson: "3.05", tier: "essential" },
  { term: `Codon chart and codon wheel`, def: `Tables of the genetic code. On the chart, find the first base on the left, second along the top and third on the right. The wheel is read from the inside (first base) to the outside (third base).`, lesson: "3.05", tier: "essential" },
  { term: `Anticodon`, def: `The 3 bases on a tRNA that pair (antiparallel and complementary) with a codon on the mRNA. For the codon 5′-AUG-3′ the anticodon is 3′-UAC-5′.`, lesson: "3.05", tier: "essential" },
  { term: `Aminoacyl-tRNA`, def: `A tRNA with its amino acid attached by an ester bond to the 3′ end (the CCA end). It is the form of tRNA that enters the A site of the ribosome.`, lesson: "3.05", tier: "essential" },
  { term: `Aminoacyl-tRNA synthetase`, def: `One of 20 enzymes, one per amino acid, that attaches the correct amino acid to the 3′ end of its tRNAs, using energy from ATP ("charging" the tRNA). It is the real translator of the code.`, lesson: "3.05", tier: "likely" },
  { term: `Wobble hypothesis`, def: `Flexible base pairing between the third base of a codon and the first base of the anticodon allows one tRNA to recognize several synonymous codons, so fewer than 61 kinds of tRNA are needed. It is why the third codon position matters least.`, lesson: "3.05", tier: "essential" },
  { term: `Ribosome`, def: `The structure of rRNA and protein that carries out translation. It has a small subunit (binds the mRNA) and a large subunit (holds the A, P and E sites and forms peptide bonds).`, lesson: "3.05", tier: "essential" },
  { term: `Small and large ribosomal subunits`, def: `The two parts of a ribosome. The small subunit binds the 5′ cap and scans the mRNA; the large subunit joins at the start codon, holds the tRNA sites and catalyzes peptide bonds.`, lesson: "3.05", tier: "essential" },
  { term: `70S and 80S ribosomes`, def: `Prokaryotic ribosomes (70S: 30S + 50S subunits) are smaller and built differently from eukaryotic cytosolic ribosomes (80S: 40S + 60S), so antibiotics can block bacterial translation without harming ours. (S = Svedberg units, a measure of sedimentation, which is why 30 + 50 ≠ 70.)`, lesson: "3.05", tier: "likely" },
  { term: `A site (aminoacyl site)`, def: `The ribosome site where each new aminoacyl-tRNA binds to the codon exposed there. A stop codon in the A site is recognized by a release factor.`, lesson: "3.05", tier: "essential" },
  { term: `P site (peptidyl site)`, def: `The ribosome site that holds the tRNA carrying the growing polypeptide chain. The initiator Met-tRNA starts here.`, lesson: "3.05", tier: "essential" },
  { term: `E site (exit site)`, def: `The ribosome site where an empty tRNA, having given up its amino acid, waits before it leaves the ribosome.`, lesson: "3.05", tier: "essential" },
  { term: `Initiator tRNA`, def: `The aminoacyl-tRNA carrying methionine (anticodon 3′-UAC-5′) that binds the start codon AUG. It is the only tRNA that enters the P site directly.`, lesson: "3.05", tier: "essential" },
  { term: `Peptide bond`, def: `The covalent bond between the carboxyl group of one amino acid and the amino group of the next, formed in a dehydration (condensation) reaction. In translation it forms between the amino acids in the P and A sites.`, lesson: "3.05", tier: "essential" },
  { term: `Peptidyl transferase`, def: `The catalytic activity in the large subunit that forms each peptide bond, moving the growing chain from the P-site tRNA onto the amino acid in the A site. It is carried out by rRNA, so the ribosome is a ribozyme.`, lesson: "3.05", tier: "likely" },
  { term: `Translocation (translation)`, def: `The shift of the ribosome one codon (3 nucleotides) toward the 3′ end of the mRNA: the tRNA in the P site moves to the E site and leaves, and the tRNA in the A site moves to the P site, leaving the A site empty. Not the same as a chromosomal translocation.`, lesson: "3.05", tier: "essential" },
  { term: `Release factor`, def: `A protein shaped like a tRNA that recognizes and binds a stop codon in the A site. It triggers hydrolysis of the bond between the polypeptide and the tRNA in the P site, releasing the chain, and the ribosome comes apart.`, lesson: "3.05", tier: "essential" },
  { term: `Polypeptide`, def: `A chain of amino acids joined by peptide bonds, the direct product of translation. It folds (sometimes with other chains) into a functional protein.`, lesson: "3.05", tier: "essential" },
  { term: `Polyribosome (polysome)`, def: `Several ribosomes translating the same mRNA at once, one behind the other, so many copies of a polypeptide are made quickly from one mRNA.`, lesson: "3.05", tier: "likely" },
  { term: `Coupled transcription and translation`, def: `In prokaryotes, ribosomes attach to an mRNA and start translating it while it is still being transcribed, because there is no nucleus to separate the two processes.`, lesson: "3.05", tier: "likely" },
  { term: `Signal sequence`, def: `A short stretch of amino acids at the start of a new polypeptide that directs its ribosome to the rough ER, so proteins for secretion or membranes are made there.`, lesson: "3.05", tier: "likely" },
  { term: `Post-translational modification`, def: `A change made to a polypeptide after translation that activates, targets or regulates it: proteolytic cleavage, phosphorylation, glycosylation, carboxylation and folding by chaperones.`, lesson: "3.05", tier: "essential" },
  { term: `Proteolytic cleavage`, def: `Enzymatic removal of peptide segments from a polypeptide, for example removing the first methionine or cutting an inactive precursor (such as proinsulin) into its active form.`, lesson: "3.05", tier: "essential" },
  { term: `Phosphorylation (of a protein)`, def: `Adding a phosphate group to certain amino acids (such as serine, threonine or tyrosine) to switch protein activity on or off.`, lesson: "3.05", tier: "essential" },
  { term: `Glycosylation`, def: `Addition of complex sugar (carbohydrate) chains to a protein to form a glycoprotein, mainly in the ER and Golgi; important for membrane and secreted proteins.`, lesson: "3.05", tier: "essential" },
  { term: `Carboxylation`, def: `Addition of a carboxyl group to specific amino acids, for example to glutamates in blood-clotting proteins (a vitamin K–dependent step), which lets them bind calcium.`, lesson: "3.05", tier: "essential" },
  { term: `Chaperone protein`, def: `A protein that helps linear polypeptide chains fold into their active 3D shapes and keeps them from clumping.`, lesson: "3.05", tier: "essential" },

  /* ---------- 3.06 Mutations ---------- */
  { term: `Mutation`, def: `A permanent change in the nucleotide sequence of a cell's DNA. It may have a negative effect, a positive effect or no effect.`, lesson: "3.06", tier: "essential" },
  { term: `Wild type`, def: `The normal, most common (unmutated) form of a gene, sequence or trait, used as the reference for describing a mutation.`, lesson: "3.06", tier: "essential" },
  { term: `Heritable (germ-line) mutation`, def: `A mutation in gametes (sperm or eggs) or the cells that make them. It can be passed on to offspring and will be in every cell of the child.`, lesson: "3.06", tier: "essential" },
  { term: `Somatic (non-heritable) mutation`, def: `A mutation in a body (somatic) cell. It is passed only to that cell's descendants in the same organism, not to offspring; many cancers start this way.`, lesson: "3.06", tier: "essential" },
  { term: `Phenotypic mutation`, def: `A temporary error made during translation (a wrong amino acid inserted), giving an altered protein even though the DNA is unchanged. It is not inherited.`, lesson: "3.06", tier: "essential" },
  { term: `Temporary (short-lived) mutation`, def: `An error in RNA or protein rather than DNA. Transcription errors are common because RNA polymerase lacks proofreading, but they are not heritable because the DNA is unchanged and each mRNA is short-lived.`, lesson: "3.06", tier: "essential" },
  { term: `Gene mutation`, def: `A change in the nucleotide sequence of one gene. Causes: DNA polymerase mispairings during replication, spontaneous decay (normal wear and tear) and mutagens.`, lesson: "3.06", tier: "essential" },
  { term: `Spontaneous mutation`, def: `A mutation that arises from normal cell processes, such as replication errors or chemical decay of DNA, without an outside cause.`, lesson: "3.06", tier: "likely" },
  { term: `Induced mutation`, def: `A mutation caused by a mutagen in the environment, such as UV light, X-rays or a chemical carcinogen.`, lesson: "3.06", tier: "likely" },
  { term: `Mutagen`, def: `An agent that increases the rate of mutation. Physical mutagens include UV light (thymine dimers) and X-rays (strand breaks); chemical mutagens include many carcinogens.`, lesson: "3.06", tier: "essential" },
  { term: `Carcinogen`, def: `A mutagen that can cause cancer, for example chemicals in tobacco smoke.`, lesson: "3.06", tier: "essential" },
  { term: `Depurination`, def: `Spontaneous loss of a purine base (A or G) from DNA when its bond to the sugar breaks, leaving a gap with no base. Thousands happen in every human cell each day and are normally repaired.`, lesson: "3.06", tier: "likely" },
  { term: `Deamination`, def: `Spontaneous loss of an amino group from a base; for example cytosine becomes uracil, which pairs with A instead of G. If not repaired, a C–G pair becomes T–A after replication.`, lesson: "3.06", tier: "likely" },
  { term: `Point mutation`, def: `A mutation involving a specific base pair: a substitution, or an insertion or deletion of one (or a few) bases.`, lesson: "3.06", tier: "essential" },
  { term: `Base-pair substitution`, def: `A point mutation in which one base pair is replaced by another. Depending on the new codon it is silent, missense or nonsense.`, lesson: "3.06", tier: "essential" },
  { term: `Silent mutation`, def: `A single base substitution that causes no change in the amino acid, because the new codon codes for the same amino acid (redundancy), for example GAG → GAA (both glutamic acid).`, lesson: "3.06", tier: "essential" },
  { term: `Missense mutation`, def: `A single base substitution that results in a different amino acid, for example GAG → GUG (glutamic acid → valine) in the sickle-cell β-globin gene. Its effect depends on how different the new amino acid is.`, lesson: "3.06", tier: "essential" },
  { term: `Nonsense mutation`, def: `A single base substitution that forms a premature stop codon, for example CAA → UAA. The polypeptide is cut short and usually non-functional.`, lesson: "3.06", tier: "essential" },
  { term: `Frameshift mutation`, def: `An insertion or deletion of one or two bases (any number not a multiple of 3) that shifts the reading frame, so every codon after it is changed, and usually an early stop codon appears.`, lesson: "3.06", tier: "essential" },
  { term: `Insertion (point mutation)`, def: `The addition of one or more extra nucleotides into a DNA sequence. One or two cause a frameshift; three add one amino acid (in-frame).`, lesson: "3.06", tier: "essential" },
  { term: `Deletion (point mutation)`, def: `The loss of one or more nucleotides from a DNA sequence. One or two cause a frameshift; three remove one amino acid (in-frame), as in the most common cystic fibrosis mutation (ΔF508).`, lesson: "3.06", tier: "essential" },
  { term: `In-frame mutation`, def: `An insertion or deletion of a multiple of three bases. The reading frame is kept, so amino acids are only added or removed at that spot.`, lesson: "3.06", tier: "likely" },
  { term: `Sickle-cell anemia`, def: `An inherited disease caused by a missense mutation in the β-globin gene (GAG → GUG), which replaces glutamic acid with valine at position 6. The hemoglobin sticks together when O<sub>2</sub> is low and the red blood cells become sickle-shaped.`, lesson: "3.06", tier: "likely" },
  { term: `Werner syndrome`, def: `An inherited disease of premature aging (shown on the mutations slide) caused by mutations in the <em>WRN</em> gene, which codes for a DNA helicase used in DNA repair and telomere maintenance.`, lesson: "3.06", tier: "likely" },
  { term: `Chromosomal mutation`, def: `A large-scale change in the structure of chromosomes and/or in chromosome number. Structural changes often come from errors during crossing over: deletion, duplication, inversion, translocation and insertion.`, lesson: "3.06", tier: "essential" },
  { term: `Deletion (chromosomal)`, def: `A section of a chromosome is removed, resulting in a loss of genetic information (A B C D E F → A B E F).`, lesson: "3.06", tier: "essential" },
  { term: `Duplication`, def: `A section of a chromosome is added from its homologous chromosome, so genes are repeated (A B C D → A B C B C D). It can raise gene dosage.`, lesson: "3.06", tier: "essential" },
  { term: `Inversion`, def: `A section of a chromosome breaks out, is reversed and reattaches (A B C D E → A D C B E). No genes are lost, but a gene cut at a break point is disrupted.`, lesson: "3.06", tier: "essential" },
  { term: `Translocation (chromosomal)`, def: `A section of one chromosome is added to a non-homologous chromosome, often as a swap between the two. It can join two genes into a fusion gene or put a gene under the wrong promoter.`, lesson: "3.06", tier: "essential" },
  { term: `Insertion (chromosomal)`, def: `A section of one chromosome is inserted into another chromosome, homologous or non-homologous (the slides list it with the other structural changes).`, lesson: "3.06", tier: "essential" },
  { term: `Homologous chromosomes`, def: `A matching pair of chromosomes, one from each parent, carrying the same genes in the same order (possibly different alleles). They pair and cross over in meiosis I.`, lesson: "3.06", tier: "essential" },
  { term: `Crossing over`, def: `Exchange of segments between homologous chromosomes during prophase I of meiosis. Errors, such as unequal crossing over between misaligned chromosomes, can cause deletions and duplications.`, lesson: "3.06", tier: "essential" },
  { term: `Aneuploidy`, def: `Having an abnormal number of chromosomes (one extra or one missing, such as trisomy 21). The slides note that most forms come from eggs with faulty cohesin proteins at the centromeres.`, lesson: "3.06", tier: "essential" },
  { term: `Cohesin`, def: `A ring-shaped protein complex that holds sister chromatids (and, through crossovers, homologous pairs) together until they are meant to separate. In eggs it is not renewed, so it weakens with maternal age and chromosomes may separate wrongly.`, lesson: "3.06", tier: "essential" },
  { term: `Nondisjunction`, def: `Failure of homologous chromosomes (meiosis I) or sister chromatids (meiosis II) to separate properly, giving gametes with an extra or a missing chromosome.`, lesson: "3.06", tier: "likely" },
  { term: `Trisomy 21 (Down syndrome)`, def: `Three copies of chromosome 21 (47 chromosomes), usually from nondisjunction in the egg. Its risk rises steeply with maternal age.`, lesson: "3.06", tier: "likely" },
  { term: `Gene dosage`, def: `The number of copies of a gene in a cell. Duplications and aneuploidy change dosage, which changes how much of a protein is made even if the protein itself is normal.`, lesson: "3.06", tier: "likely" },
  { term: `Fusion protein (BCR-ABL)`, def: `A hybrid protein made from a gene formed when a translocation joins parts of two genes. In chronic myeloid leukemia, a 9;22 translocation (the Philadelphia chromosome) fuses <em>BCR</em> to <em>ABL</em>, making an always-active enzyme that drives cell division.`, lesson: "3.06", tier: "extra" },
  { term: `Xeroderma pigmentosum`, def: `A rare inherited disease in which excision repair does not work, so UV-induced thymine dimers are not fixed. People with it are extremely sensitive to sunlight and get skin cancers at a very young age.`, lesson: "3.06", tier: "extra" },
  { term: `Lactase persistence`, def: `A beneficial mutation (a change in a regulatory sequence near the lactase gene) that keeps lactase being made into adulthood, so adults can digest milk. It spread in dairy-farming populations.`, lesson: "3.06", tier: "extra" },

  /* ---------- 3.07 Gene Regulation: Operons ---------- */
  { term: `Gene regulation`, def: `Control of when, where and how much a gene is expressed. Every cell has the same DNA, so regulation decides which proteins each cell makes, and it saves energy by not making proteins that are not needed.`, lesson: "3.07", tier: "essential" },
  { term: `Housekeeping gene`, def: `A gene that is expressed all the time in nearly every cell because its product is always needed (for example, glycolysis enzymes and ribosomal proteins).`, lesson: "3.07", tier: "likely" },
  { term: `Constitutive expression`, def: `Expression of a gene all the time, at a steady level, regardless of conditions. Mutations that destroy the repressor or operator make an operon constitutive.`, lesson: "3.07", tier: "likely" },
  { term: `Operon`, def: `A functioning unit of bacterial DNA containing a cluster of genes under the control of a single regulatory signal: a promoter, an operator and the structural genes, transcribed together as one mRNA.`, lesson: "3.07", tier: "essential" },
  { term: `Operator`, def: `The on/off switch of an operon: a DNA sequence between the promoter and the structural genes where the repressor binds. A bound repressor physically blocks RNA polymerase.`, lesson: "3.07", tier: "essential" },
  { term: `Structural genes`, def: `The genes in an operon that code for the enzymes or proteins the cell needs (<em>lacZ</em>, <em>lacY</em>, <em>lacA</em> in the lac operon; <em>trpE</em>, <em>trpD</em>, <em>trpC</em>, <em>trpB</em>, <em>trpA</em> in the trp operon).`, lesson: "3.07", tier: "essential" },
  { term: `Regulatory gene`, def: `A gene, usually just outside the operon with its own promoter, that codes for the repressor protein (<em>lacI</em> for the lac operon, <em>trpR</em> for the trp operon). It is expressed all the time at a low level.`, lesson: "3.07", tier: "essential" },
  { term: `Repressor`, def: `A protein that binds the operator and blocks transcription of an operon. A small effector molecule changes its shape: an inducer inactivates it (lac), a corepressor activates it (trp).`, lesson: "3.07", tier: "essential" },
  { term: `Polycistronic mRNA`, def: `A single mRNA that carries the code for several proteins, made when all the structural genes of an operon are transcribed together. Common in bacteria, rare in eukaryotes.`, lesson: "3.07", tier: "likely" },
  { term: `lac operon`, def: `The <em>E. coli</em> operon that controls the production of enzymes needed to break down lactose. It is inducible: off by default, switched on when lactose is present (and best when glucose is absent).`, lesson: "3.07", tier: "essential" },
  { term: `Inducible operon`, def: `An operon that is OFF by default because its repressor is active and bound to the operator. An inducer inactivates the repressor and turns it on. Typical of catabolic (breakdown) pathways, such as lac.`, lesson: "3.07", tier: "essential" },
  { term: `Inducer`, def: `A small molecule that binds a repressor, changes its shape so it releases the operator, and switches an operon on. For the lac operon it is lactose (strictly, its isomer allolactose).`, lesson: "3.07", tier: "essential" },
  { term: `Allolactose`, def: `An isomer of lactose made in small amounts by β-galactosidase. It is the molecule that actually binds the lac repressor; textbooks and the class activity usually just say "lactose".`, lesson: "3.07", tier: "likely" },
  { term: `Lac repressor gene (<em>lacI</em>)`, def: `The regulatory gene of the lac operon, which codes for the lac repressor.`, lesson: "3.07", tier: "likely" },
  { term: `β-galactosidase (<em>lacZ</em>)`, def: `The first structural gene of the lac operon. Its enzyme, β-galactosidase, hydrolyzes lactose into glucose and galactose.`, lesson: "3.07", tier: "essential" },
  { term: `Lactose permease (<em>lacY</em>)`, def: `The second structural gene of the lac operon. It codes for lactose permease, a membrane protein that brings lactose into the cell.`, lesson: "3.07", tier: "essential" },
  { term: `Transacetylase (<em>lacA</em>)`, def: `The third structural gene of the lac operon. It codes for thiogalactoside transacetylase, an enzyme whose role in lactose use is minor (it is thought to help detoxify similar sugars).`, lesson: "3.07", tier: "likely" },
  { term: `trp operon`, def: `The <em>E. coli</em> operon of five structural genes (<em>trpE</em>, <em>D</em>, <em>C</em>, <em>B</em>, <em>A</em>) for the enzymes that synthesize the amino acid tryptophan. It is repressible: on by default, switched off when tryptophan is plentiful.`, lesson: "3.07", tier: "essential" },
  { term: `Repressible operon`, def: `An operon that is ON by default because its repressor is made inactive. A corepressor activates the repressor and turns it off. Typical of anabolic (synthesis) pathways, such as trp.`, lesson: "3.07", tier: "essential" },
  { term: `Corepressor`, def: `A small molecule that binds an inactive repressor and activates it, so it binds the operator and stops transcription. For the trp operon the corepressor is tryptophan, the end product of the pathway.`, lesson: "3.07", tier: "essential" },
  { term: `Trp repressor gene (<em>trpR</em>)`, def: `The regulatory gene for the trp operon, which codes for the trp repressor. It is located far away from the operon on the <em>E. coli</em> chromosome.`, lesson: "3.07", tier: "likely" },
  { term: `Negative control`, def: `Regulation in which a repressor protein turns genes off by binding DNA. Both the lac and trp repressor systems are negative control.`, lesson: "3.07", tier: "likely" },
  { term: `Positive control`, def: `Regulation in which an activator protein turns genes on, or up, by binding DNA and helping RNA polymerase bind the promoter. CAP is the activator of the lac operon.`, lesson: "3.07", tier: "likely" },
  { term: `CAP (catabolite activator protein)`, def: `An activator protein that, when bound to cAMP, attaches to a site next to the lac promoter and helps RNA polymerase bind, boosting transcription. It is active only when glucose is scarce.`, lesson: "3.07", tier: "likely" },
  { term: `cAMP (cyclic AMP)`, def: `A small signalling molecule made from ATP. Its level in <em>E. coli</em> rises when glucose is scarce; it binds CAP and activates it.`, lesson: "3.07", tier: "likely" },
  { term: `Catabolite repression`, def: `The preference of <em>E. coli</em> for glucose: while glucose is present, cAMP is low, CAP is inactive and operons for other sugars, such as lac, are transcribed only weakly even if their sugar is present.`, lesson: "3.07", tier: "likely" },
  { term: `Diauxic growth`, def: `Two-phase growth of bacteria given glucose and lactose together: they use glucose first, pause while the lac operon switches on, then grow on lactose.`, lesson: "3.07", tier: "extra" },
  { term: `Feedback inhibition`, def: `Control in which the end product of a pathway inhibits an earlier step. Tryptophan both represses the trp operon (slow, saves making enzymes) and inhibits the first enzyme of its pathway (fast).`, lesson: "3.07", tier: "likely" },
  { term: `Attenuation`, def: `A second control of the trp operon in which a stretch of mRNA near the start forms a terminator hairpin and stops transcription early when tryptophan is plentiful. It works because transcription and translation are coupled in bacteria.`, lesson: "3.07", tier: "extra" },
  { term: `Epigenetics`, def: `Heritable changes in gene expression that do not change the DNA sequence, such as DNA methylation and histone modifications. They help explain how cells with the same DNA become different cell types.`, lesson: "3.07", tier: "extra" },
  { term: `DNA methylation`, def: `Adding methyl groups to cytosines (mostly at CG sites), especially in promoters. It usually silences genes and is copied when DNA is replicated.`, lesson: "3.07", tier: "extra" },
  { term: `Histone acetylation`, def: `Adding acetyl groups to histone tails, which removes their positive charge, loosens chromatin and makes genes easier to transcribe. Removing them tightens chromatin.`, lesson: "3.07", tier: "extra" },
  { term: `Enhancer`, def: `A eukaryotic DNA sequence, which can be thousands of base pairs from the gene, that binds activator proteins; the DNA loops so the activators contact the promoter and increase transcription.`, lesson: "3.07", tier: "extra" }
);
